use std::collections::{HashMap,BinaryHeap};use std::cmp::Reverse;impl Solution{pub fn find_itinerary(t:Vec<Vec<String>>)->Vec<String>{fn f(u:String,g:&mut HashMap<String,BinaryHeap<Reverse<String>>>,o:&mut Vec<String>){loop{let v=g.get_mut(&u).and_then(|q|q.pop()).map(|x|x.0);if let Some(x)=v{f(x,g,o)}else{break}}o.push(u);}let mut g:HashMap<String,BinaryHeap<Reverse<String>>>=HashMap::new();for x in t{g.entry(x[0].clone()).or_default().push(Reverse(x[1].clone()));}let mut o=vec![];f("JFK".into(),&mut g,&mut o);o.reverse();o}}
